<?php $conn = new mysqli("localhost", "root", "", "db_forecasting_iphone"); $data = []; foreach(["IP13", "IP14PM", "IP15P"] as $id) { $res = $conn->query("SELECT DATE_FORMAT(tanggal_transaksi, '%Y-%m') as bulan_tahun, SUM(jumlah_terjual) as total_terjual FROM data_penjualan WHERE id_iphone='$id' GROUP BY DATE_FORMAT(tanggal_transaksi, '%Y-%m') ORDER BY DATE_FORMAT(tanggal_transaksi, '%Y-%m') ASC"); while ($row = $res->fetch_assoc()) { $data[$id][] = $row; } } echo "<pre>" . json_encode($data, JSON_PRETTY_PRINT) . "</pre>"; ?>
